//! P2 eval parity gate, C engine side (docs/plans/PLAN_03_rust_port.md
//! "Parity verification"). Fixture is generated by driving the built
//! `engine/shatrunz_engine` UCI binary (`engine/evaluate.c`'s `evaluate()`,
//! the function the `eval` UCI command actually calls). Regenerate with:
//!
//! ```sh
//! make -C engine
//! python3 tools/c/eval_dump.py > crates/shatrunz-core/tests/fixtures/eval_engine_fixture.json
//! ```

use serde::Deserialize;
use shatrunz_core::eval::engine::evaluate;
use shatrunz_core::game::Game;
use shatrunz_core::moves::{MoveTarget, Square};

#[derive(Debug, Deserialize)]
struct Fixture {
    positions: Vec<PositionCase>,
}

#[derive(Debug, Deserialize)]
struct PositionCase {
    label: String,
    #[serde(rename = "uciMoves")]
    uci_moves: Vec<String>,
    score_cp: i32,
}

fn load_fixture() -> Fixture {
    let raw = include_str!("fixtures/eval_engine_fixture.json");
    serde_json::from_str(raw).expect("eval_engine_fixture.json must parse")
}

/// Same minimal UCI move parser as tests/eval_hce_parity.rs: file a-i,
/// rank = 9-row (engine/uci.c's square_to_uci, mirrored by parse side).
fn parse_uci(uci: &str) -> (Square, MoveTarget) {
    let bytes = uci.as_bytes();
    let from_file = (bytes[0] - b'a') as usize;
    let from_rank: usize = (bytes[1] - b'0') as usize;
    let to_file = (bytes[2] - b'a') as usize;
    let to_rank: usize = (bytes[3] - b'0') as usize;
    let from = Square { r: 9 - from_rank, c: from_file };
    let to = MoveTarget::plain(9 - to_rank, to_file);
    (from, to)
}

#[test]
fn engine_eval_matches_c_binary() {
    let fixture = load_fixture();
    for case in &fixture.positions {
        let mut game = Game::new();
        for uci in &case.uci_moves {
            let (from, to) = parse_uci(uci);
            assert!(game.execute_move(from, to), "{}: replay move {uci} failed", case.label);
        }
        let score = evaluate(&game.board, game.turn);
        assert_eq!(score, case.score_cp, "{}: evaluate() mismatch", case.label);
    }
}
